function [fields,info,cPlus,cMinus] = runDNS(problem,frequencies)
    % Code has been varified by Martin (generated by AI initially though)
    fprintf('[DNS] Setting up mesh, permittivity and PML.\n');
    setupTimer = tic;
    % set up the grid and the materials which don't have frequency
    % components
    gridData = mesh.create(problem);
    e = geometry.generatePermittivity(problem,gridData);
    [sgmx,sgmy] = fdfd.buildPML(problem,gridData,e);
    info.setupTime = toc(setupTimer);
    fprintf('[DNS] Setup finished in %.1f s.\n',info.setupTime);

    fields = cell(numel(frequencies),1);
    % Rows are probes; columns follow the supplied frequency order.
    cPlus = complex(zeros(numel(problem.probes),numel(frequencies)));
    cMinus = complex(zeros(numel(problem.probes),numel(frequencies)));
    info.assemblyTime = zeros(numel(frequencies),1);
    info.solveTime = zeros(numel(frequencies),1);
    info.portTime = zeros(numel(frequencies),1);
    
    assemblyTime = zeros(numel(frequencies),1);
    solveTime = zeros(numel(frequencies),1);
    portTime = zeros(numel(frequencies),1);
    fprintf('[DNS] Starting parallel sweep of %d frequencies.\n',numel(frequencies));
    sweepTimer = tic;
    parfor j = 1:numel(frequencies)
        w = frequencies(j);
        fprintf('[DNS] Frequency %d/%d: source and assembly started.\n',j,numel(frequencies));
        timer = tic;

        [phi,beta] = fdfd.buildSource( ...
            e,gridData,w,problem,sgmx,sgmy);

        switch problem.polarization
            case "TE"
                A = fdfd.assembleTE(gridData,w,e,sgmx,sgmy);
            case "TM"
                A = fdfd.assembleTM(gridData,w,e,sgmx,sgmy);
            otherwise
                error('Polarization must be "TE" or "TM".');
        end

        b = fdfd.applyQAAQ(gridData,A,phi,beta,problem);
        assemblyTime(j) = toc(timer);
        fprintf('[DNS] Frequency %d/%d: assembly done (%.1f s); linear solve started.\n',j,numel(frequencies),assemblyTime(j));

        timer = tic;
        fields{j} = A \ b;
        solveTime(j) = toc(timer);
        fprintf('[DNS] Frequency %d/%d: solve done (%.1f s); port extraction started.\n',j,numel(frequencies),solveTime(j));

        timer = tic;
        [cp,cn] = ports.SolveProb( ...
            e,sgmx,sgmy,w,gridData,fields{j},problem);
        cPlus(:,j) = cp;
        cMinus(:,j) = cn;
        portTime(j) = toc(timer);
        fprintf('[DNS] Frequency %d/%d complete: assembly %.1f s, solve %.1f s, ports %.1f s.\n', ...
            j,numel(frequencies),assemblyTime(j),solveTime(j),portTime(j));
    end
    info.assemblyTime = assemblyTime;
    info.solveTime = solveTime;
    info.portTime = portTime;
    info.totalTime = info.setupTime + toc(sweepTimer);
    fprintf('[DNS] Sweep finished; total elapsed including setup: %.1f s.\n',info.totalTime);
end
